612:         private async Task CleanupAsync()
613:         {
614:             // Kept for compatibility if called elsewhere; perform best-effort synchronous-ish cleanup then return quickly.
615:             try
616:             {
617:                 // Close child windows quickly on UI thread where necessary (best-effort)
618:                 foreach (var tv in TrackViews.ToList())
619:                 {
620:                     try
621:                     {
622:                         if (tv == null)
623:                         {
624:                             continue;
625:                         }
626: 
627:                         if (!tv.IsDisposed)
628:                         {
629:                             if (tv.InvokeRequired)
630:                             {
631:                                 try { tv.Invoke((Action)tv.Close); } catch { /* ignore */ }
632:                             }
633:                             else
634:                             {
635:                                 try { tv.Close(); } catch { /* ignore */ }
636:                             }
637:                         }
638:                     }
639:                     catch { /* ignore individual child errors */ }
640:                 }
641: 
642:                 // Stop and dispose timer if present
643:                 try
644:                 {
645:                     if (this.recordingTimer != null)
646:                     {
647:                         try { this.recordingTimer.Stop(); } catch { }
648:                         try { this.recordingTimer.Dispose(); } catch { }
649:                         this.recordingTimer = null;
650:                     }
651:                 }
652:                 catch { }
653: 
654:                 // Do not block the UI shutdown long â€” attempt to clear audio collection but with a short timeout.
655:                 try
656:                 {
657:                     var clearTask = this.AudioC.ClearAsync();
658:                     // Wait briefly to allow cleanup to start but do not block shutdown indefinitely
659:                     var completed = await Task.WhenAny(clearTask, Task.Delay(2000)).ConfigureAwait(false);
660:                     if (completed == clearTask)
661:                     {
662:                         // allow potential exceptions to surface to the catch below
663:                         await clearTask.ConfigureAwait(false);
664:                     }
665:                 }
666:                 catch { /* swallow - best-effort */ }
667: 
668:                 // Finally try to exit threads cleanly (best-effort)
669:                 try { Application.ExitThread(); } catch { }
670:             }
671:             catch (Exception ex)
672:             {
673:                 try { LogManager.Log($"CleanupAsync: Exception during cleanup: {ex.Message}"); } catch { }
674:             }
675:             finally
676:             {
677:                 // Last resort: ensure process terminates (non-returning)
678:                 try { Environment.Exit(0); } catch { }
679:             }
680:         }
