697:         public long GetSampleAtSeconds(double seconds)
698:         {
699:             // Guard
700:             if (this.SampleRate <= 0 || this.Data == null || this.Data.Length == 0 || this.Channels <= 0)
701:             {
702:                 return 0;
703:             }
704: 
705:             if (double.IsNaN(seconds) || double.IsInfinity(seconds))
706:             {
707:                 return 0;
708:             }
709: 
710:             // Use base sample rate (frames = samples per channel)
711:             long totalFrames = this.Data.Length / this.Channels;
712: 
713:             // Clamp seconds to valid range
714:             if (seconds <= 0.0)
715:             {
716:                 return 0;
717:             }
718: 
719:             if (seconds >= this.Duration.TotalSeconds)
720:             {
721:                 return totalFrames - 1;
722:             }
723: 
724:             // Compute frame index (floor to avoid stepping past requested time)
725:             long frameIndex = (long)Math.Floor(seconds * this.SampleRate);
726: 
727:             // Ensure within bounds [0, totalFrames-1]
728:             frameIndex = Math.Clamp(frameIndex, 0L, Math.Max(0L, totalFrames - 1));
729: 
730:             return frameIndex;
731:         }
