734:         {
735:             if (this.BeatGrid == null || this.BeatGrid.Length == 0)
736:             {
737:                 long totalFrames = this.Length / Math.Max(1, this.Channels);
738:                 if (totalFrames <= 0)
739:                 {
740:                     return 0;
741:                 }
742:                 return Math.Clamp(frameIndex, 0L, totalFrames - 1);
