751:             long clamped = Math.Clamp(frameIndex, 0L, total - 1);
752:             int center = (int)clamped;
753: 
754:             if (this.BeatGrid[center])
755:             {
756:                 return center;
757:             }
758: 
759:             int maxDistance = total - 1;
760:             for (int d = 1; d <= maxDistance; d++)
761:             {
762:                 int left = center - d;
763:                 if (left >= 0 && this.BeatGrid[left])
764:                 {
765:                     return left;
766:                 }
