109:         public bool LoadAudioFile()
110:         {
111:             if (string.IsNullOrWhiteSpace(this.FilePath))
112:             {
113:                 return false;
114:             }
115: 
116:             this.Name = Path.GetFileNameWithoutExtension(this.FilePath);
117:             this.OriginalName = this.Name;
118:             Stopwatch sw = Stopwatch.StartNew();
119: 
120:             try
121:             {
122:                 using var reader = new AudioFileReader(this.FilePath);
123:                 this.SampleRate = reader.WaveFormat.SampleRate;
124:                 this.Channels = reader.WaveFormat.Channels;
125:                 this.BitDepth = reader.WaveFormat.BitsPerSample;
126: 
127:                 // reader.WaveFormat is the 32-bit IEEE float output format, so its
128:                 // BlockAlign is 4 * channels. reader.Length is the float byte length
129:                 // (frames * 4 * channels). Dividing by sizeof(float) yields the total
130:                 // interleaved sample count (frames * channels). Dividing by BlockAlign
131:                 // instead would give only the per-channel frame count, which for
132:                 // multi-channel audio is a fraction (e.g. half for stereo) of the
133:                 // samples actually present.
134:                 long numSamples = reader.Length > 0
135:                     ? reader.Length / sizeof(float)
136:                     : 0;
137: 
138:                 // Use streaming for files that would exceed int.MaxValue samples
139:                 if (numSamples > int.MaxValue)
140:                 {
141:                     this.Data = ReadAllSamplesStreaming(reader).ToArray();
142:                 }
143:                 else if (numSamples > 0)
144:                 {
145:                     float[] tmp = new float[checked((int)numSamples)];
146:                     int read = reader.Read(tmp.AsSpan());
147:                     if (read != numSamples)
148:                     {
149:                         float[] resized = new float[checked((int)read)];
150:                         Array.Copy(tmp, resized, read);
151:                         this.Data = resized;
152:                     }
153:                     else
154:                     {
155:                         this.Data = tmp;
156:                     }
157:                 }
158:                 else
159:                 {
160:                     this.Data = ReadAllSamplesStreaming(reader).ToArray();
161:                 }
162: 
163:                 this.Length = this.Data.Length;
164:                 this.Duration = reader.TotalTime;
165:             }
166:             catch (Exception ex)
167:             {
168:                 LogCollection.Log($"Error loading audio file: {ex.Message}");
169:                 this.Dispose();
170:                 return false;
171:             }
172: 
173:             this["Import"] = sw.Elapsed.TotalMilliseconds;
174:             sw.Restart();
175:             this.ReadBpmTag();
176:             this["ReadBpmTag"] = sw.Elapsed.TotalMilliseconds;
177: 
178:             return true;
