280:         private static IEnumerable<float> ReadAllSamplesStreaming(AudioFileReader reader)
281:         {
282:             // FIX: Previously only 'channels' samples were read per iteration causing thousands of tiny reads.
283:             // Use a per-channel block of 1 second for efficient streaming.
284:             const int blockSeconds = 1;
285:             int channels = Math.Max(1, reader.WaveFormat.Channels);
286:             int samplesPerChannelPerBlock = reader.WaveFormat.SampleRate * blockSeconds;
287:             int blockSize = samplesPerChannelPerBlock * channels; // total interleaved samples
288:             float[] buffer = new float[checked((int)blockSize)];
289:             int read;
290:             var sampleProvider = reader.ToSampleProvider();
291:             while ((read = sampleProvider.Read(buffer.AsSpan())) > 0)
292:             {
293:                 for (int i = 0; i < read; i++)
294:                 {
295:                     yield return buffer[i];
296:                 }
297:             }
298:         }
