176:     private void UpdateTimeLabels(double progress, bool sampleProgress = false)
177:     {
178:         TimeSpan elapsed = this.stopwatch.Elapsed;
179:         this.label_elapsed.Text = $"Elapsed: {this.FormatTime(elapsed)}";
180:         if (this.progress == null)
181:         {
182:             return;
183:         }
184: 
185:         double elapsedSeconds = elapsed.TotalSeconds;
186:         double fractionDelta = progress - this.lastRateSampleFraction;
187:         double elapsedDelta = elapsedSeconds - this.lastRateSampleSeconds;
188:         if (sampleProgress
189:             && fractionDelta > 0.0001
190:             && elapsedDelta >= MinimumRateSampleIntervalSeconds)
191:         {
192:             double instantRate = fractionDelta / elapsedDelta;
193:             double maximumRate = GetMaximumPlausibleRate(progress, elapsedSeconds);
194:             instantRate = Math.Min(instantRate, maximumRate);
195:             this.smoothedProgressRate = this.smoothedProgressRate <= 0
196:                 ? instantRate
197:                 : (this.smoothedProgressRate * 0.72) + (instantRate * 0.28);
198:             this.smoothedProgressRate = Math.Min(this.smoothedProgressRate, maximumRate);
199:             this.lastRateSampleFraction = progress;
200:             this.lastRateSampleSeconds = elapsedSeconds;
201:             this.progressRateSampleCount++;
202:         }
203: 
204:         TimeSpan proposed = TimeSpan.Zero;
205:         double estimatedRate = Math.Min(
206:             this.smoothedProgressRate,
207:             GetMaximumPlausibleRate(progress, elapsedSeconds));
208:         if (this.progressRateSampleCount >= 2
209:             && elapsedSeconds >= 5
210:             && estimatedRate > 0.000001
211:             && progress < 1.0)
212:         {
213:             double totalSeconds = elapsedSeconds + ((1.0 - progress) / estimatedRate);
214:             var candidate = TimeSpan.FromSeconds(Math.Clamp(totalSeconds, 0, TimeSpan.MaxValue.TotalSeconds));
215:             if (this.smoothedCompletionTime is null)
216:             {
217:                 this.smoothedCompletionTime = candidate;
218:             }
219:             else
220:             {
221:                 double mixedSeconds = (this.smoothedCompletionTime.Value.TotalSeconds * 0.80)
222:                     + (candidate.TotalSeconds * 0.20);
223:                 this.smoothedCompletionTime = TimeSpan.FromSeconds(
224:                     Math.Clamp(mixedSeconds, elapsedSeconds, TimeSpan.MaxValue.TotalSeconds));
225:             }
226: 
227:             proposed = this.smoothedCompletionTime.Value;
228:         }
229:         else if (progress >= 1.0)
230:         {
231:             proposed = elapsed;
232:         }
233: 
234:         this.label_proposed.Text = proposed > TimeSpan.Zero && progress > 0.0001
235:             ? $"Proposed time: {this.FormatTime(proposed)}"
236:             : "Proposed time: --:--.---";
237:     }
