538:             if (string.IsNullOrWhiteSpace(baseDir) || !Directory.Exists(baseDir))
539:             {
540:                 baseDir = Environment.GetFolderPath(Environment.SpecialFolder.MyMusic);
541:             }
542: 
543:             Random rand = new();
544: 
545:             string[] allAudioFiles = Directory.Exists(baseDir)
546:                 ? Directory.EnumerateFiles(baseDir, "*.*", SearchOption.AllDirectories)
547:                     .Where(f => AllowedImportExtensions.Contains(Path.GetExtension(f)))
548:                     .ToArray()
549:                 : Array.Empty<string>();
550: 
551:             // Random selection: pick a random file, load it, and keep it only if its
552:             // duration is shorter than 12 minutes. Try another file otherwise.
553:             const double maxDurationSeconds = 12.0 * 60.0;
