561:                 var loaded = (await this.AudioC.LoadManyAsync([candidate])).ToList();
562:                 var audio = loaded.FirstOrDefault(a => a != null);
563:                 if (audio != null && audio.Duration.TotalSeconds < maxDurationSeconds)
564:                 {
565:                     randomAudio = audio;
566:                 }
567:                 else
568:                 {
569:                     if (audio != null)
570:                     {
571:                         this.AudioC.Audios.Remove(audio);
