577:             if (randomAudio == null)
578:             {
579:                 LogManager.Log("Random import: No audio files shorter than 12 minutes found.");
580:                 return;
581:             }
582: 
583:             // Import into an existing AudioCollectionView (not a new one)
584:             var importDir = Path.GetDirectoryName(randomAudio.FilePath) ?? string.Empty;
