689: 
690:             var collectedPaths = new List<string>();
691:             foreach (var path in dropped.Where(p => !string.IsNullOrWhiteSpace(p)))
692:             {
693:                 try
694:                 {
695:                     if (Directory.Exists(path))
696:                     {
697:                         var found = Directory.EnumerateFiles(path, "*.*", SearchOption.AllDirectories)
698:                             .Where(f => AllowedImportExtensions.Contains(Path.GetExtension(f)));
699:                         collectedPaths.AddRange(found);
700:                     }
701:                     else if (File.Exists(path) && AllowedImportExtensions.Contains(Path.GetExtension(path)))
702:                     {
703:                         collectedPaths.Add(path);
704:                     }
705:                 }
706:                 catch (Exception ex)
707:                 {
708:                     LogManager.Log($"DragDrop: error scanning '{path}': {ex.Message}");
709:                 }
710:             }
711: 
712:             var validPaths = collectedPaths.Distinct(StringComparer.OrdinalIgnoreCase).ToList();
713:             if (validPaths.Count == 0)
714:             {
715:                 LogManager.Log("DragDrop: No allowed audio files found in drop.");
716:                 return;
717:             }
718: 
719:             try { this.lastImportFolder = Path.GetDirectoryName(validPaths[0]) ?? this.lastImportFolder; } catch { }
720:             await this.ImportAndPlaceAsync(validPaths, fromResources: false);
