723:         private async Task ImportAndPlaceAsync(IEnumerable<string> filePaths, bool fromResources)
724:         {
725:             var validPaths = filePaths.Where(p => !string.IsNullOrWhiteSpace(p)).ToList();
726:             if (validPaths.Count == 0)
727:             {
728:                 return;
729:             }
730: 
731:             var loaded = (await this.AudioC.LoadManyAsync(validPaths)).ToList();
732:             // LoadManyAsync omits failed files. Zipping its compacted results
733:             // with requested indices assigned later tracks to the wrong folder.
734:             var pairs = loaded.OfType<AudioObj>()
735:                 .Select(audio => (Path: Path.GetFullPath(audio.FilePath), Audio: audio))
736:                 .ToList();
737: 
738:             var importedAudios = pairs.Select(x => x.Audio!).ToList();
739:             if (importedAudios.Count == 0)
740:             {
741:                 return;
742:             }
743: 
744:             foreach (var audio in importedAudios)
745:             {
746:                 LogManager.Log(fromResources ? $"{audio.Name} imported from resources." : $"{audio.Name} imported.");
747:             }
748: 
749:             this.PlaceImportedAudios(pairs, importedAudios);
750: 
751:             foreach (var audio in importedAudios)
752:             {
753:                 this.AudioC.Audios.Remove(audio);
754:             }
755:         }
