180:         if (!Directory.Exists(current)) return;
181:         try
182:         {
183:             foreach (string directory in Directory.EnumerateDirectories(BinaryDirectory, tool + "-*", SearchOption.TopDirectoryOnly))
184:             {
185:                 if (string.Equals(directory, current, StringComparison.OrdinalIgnoreCase)) continue;
186:                 string suffix = Path.GetFileName(directory)[(tool.Length + 1)..];
187:                 // Only remove version directories created by this manager, never user folders or directory links.
188:                 if (suffix.Length != 97 || suffix[64] != '-' || !IsHex(suffix[..64], 64) || !IsHex(suffix[65..], 32)) continue;
189:                 try
190:                 {
191:                     if ((File.GetAttributes(directory) & FileAttributes.ReparsePoint) != 0) continue;
192:                     Directory.Delete(directory, recursive: true);
193:                     progress?.Report($"Removed old {tool} version: {Path.GetFileName(directory)}.");
194:                 }
195:                 catch (Exception error) when (error is IOException or UnauthorizedAccessException)
196:                 {
197:                     progress?.Report($"Warning: Unable to remove old {tool} version; cleanup will retry on the next update check. {error.Message}");
198:                 }
199:             }
200:         }
201:         catch (Exception error) when (error is IOException or UnauthorizedAccessException)
202:         {
203:             progress?.Report($"Warning: Unable to enumerate old {tool} versions for cleanup. {error.Message}");
204:         }
205:     }
206: 
207:     private static async Task ExtractExecutablesAsync(string package, string destination, string[] files,
208:         CancellationToken token)
209:     {
210:         using var archive = ZipFile.OpenRead(package);
211:         foreach (var file in files)
212:         {
213:             token.ThrowIfCancellationRequested();
214:             var entry = archive.Entries.SingleOrDefault(e => IsExecutableEntry(e, file))
215:                 ?? throw new InvalidDataException($"The archive does not contain {file}.");
216:             if (entry.Length is < 2 or > 536870912)
217:                 throw new InvalidDataException("The extracted executable exceeds the allowed size.");
218:             await using var source = entry.Open();
219:             await using var target = new FileStream(Path.Combine(destination, file), FileMode.CreateNew,
220:                 FileAccess.Write, FileShare.None, 81920, FileOptions.Asynchronous);
221:             var buffer = new byte[81920];
222:             long total = 0;
223:             int count;
224:             while ((count = await source.ReadAsync(buffer.AsMemory(), token)) > 0)
225:             {
226:                 total += count;
227:                 if (total > entry.Length)
228:                     throw new InvalidDataException("The archive entry exceeded its declared size.");
229:                 await target.WriteAsync(buffer.AsMemory(0, count), token);
230:             }
231:             if (total != entry.Length)
232:                 throw new InvalidDataException("The archive entry is truncated.");
233:         }
234:     }
235: 
236:     private static bool IsExecutableEntry(ZipArchiveEntry entry, string file)
237:     {
238:         var segments = entry.FullName.Replace('\\', '/').Split('/');
239:         return string.Equals(segments[^1], file, StringComparison.OrdinalIgnoreCase) &&
240:             segments.All(segment => segment.Length > 0 && segment is not ("." or "..") && !segment.Contains(':'));
241:     }
242: 
243:     private static async Task<Dictionary<string, string>> VerifyExecutablesAsync(string directory, string[] files,
244:         CancellationToken token)
245:     {
246:         var hashes = new Dictionary<string, string>(StringComparer.Ordinal);
247:         foreach (var file in files)
248:         {
249:             var path = Path.Combine(directory, file);
250:             using (var stream = File.OpenRead(path))
251:                 if (stream.ReadByte() != 'M' || stream.ReadByte() != 'Z')
252:                     throw new InvalidDataException($"{file} is not a Windows executable.");
253:             hashes[file] = await GitHubReleaseSource.HashAsync(path, token);
254:         }
255:         return hashes;
256:     }
257: 
258:     private async Task<bool> IsCurrentAsync(string tool, string hash, string[] files, CancellationToken token)
259:     {
260:         var state = ReadState(tool);
261:         return state?.PackageHash == hash && await IsUsableAsync(tool, files, token);
262:     }
263: 
264:     private async Task<bool> IsUsableAsync(string tool, string[] files, CancellationToken token)
265:     {
266:         var state = ReadState(tool);
267:         var directory = GetInstalledDirectory(tool, files);
268:         if (state is null || directory is null)
269:             return false;
270:         try
271:         {
272:             foreach (var file in files)
273:                 if (!state.FileHashes.TryGetValue(file, out var hash) ||
274:                     !string.Equals(hash, await GitHubReleaseSource.HashAsync(Path.Combine(directory, file), token),
275:                         StringComparison.OrdinalIgnoreCase))
276:                     return false;
277:             return true;
278:         }
279:         catch (IOException) { return false; }
280:         catch (UnauthorizedAccessException) { return false; }
281:     }
282: 
283:     private string? GetInstalledDirectory(string tool, string[] files)
284:     {
285:         var state = ReadState(tool);
286:         if (state is null)
287:             return null;
288:         var directory = StateDirectory(tool, state);
289:         return files.All(file => File.Exists(Path.Combine(directory, file))) ? directory : null;
290:     }
291: 
292:     private InstalledState? ReadState(string tool)
293:     {
294:         try
295:         {
296:             var path = MarkerPath(tool);
297:             if (!File.Exists(path) || new FileInfo(path).Length > 8192)
298:                 return null;
299:             var state = JsonSerializer.Deserialize<InstalledState>(File.ReadAllText(path));
300:             return state is not null && IsHex(state.PackageHash, 64) && IsHex(state.InstallId, 32) &&
301:                 state.FileHashes is not null ? state : null;
302:         }
303:         catch (Exception error) when (error is IOException or UnauthorizedAccessException or JsonException)
304:         { return null; }
305:     }
306: 
307:     private static bool IsHex(string? value, int length) =>
308:         value?.Length == length && value.All(char.IsAsciiHexDigit);
309: 
310:     private string MarkerPath(string tool) => Path.Combine(BinaryDirectory, tool + ".installed.json");
311:     private string StateDirectory(string tool, InstalledState state) =>
312:         Path.Combine(BinaryDirectory, $"{tool}-{state.PackageHash}-{state.InstallId}");
313: 
314:     internal string? FindDeno()
315:     {
316:         // A fresh browser/client must discover the persisted installation without
317:         // requiring UpdateDenoAsync (and therefore GitHub requests) first.
318:         verifiedDenoDirectory ??= GetInstalledDirectory("deno", DenoFiles);
319:         if (verifiedDenoDirectory is not null)
320:         {
321:             var path = Path.Combine(verifiedDenoDirectory, "deno.exe");
322:             if (File.Exists(path))
323:                 return path;
324:         }
325:         return fallbackDenoPath is not null && File.Exists(fallbackDenoPath) ? fallbackDenoPath : null;
326:     }
327: 
328:     private static string? FindDenoOnPath()
329:     {
330:         foreach (var entry in (Environment.GetEnvironmentVariable("PATH") ?? string.Empty).Split(Path.PathSeparator))
331:         {
332:             var directory = entry.Trim().Trim('"');
333:             if (!Path.IsPathFullyQualified(directory))
334:                 continue;
335:             try
336:             {
337:                 var path = Path.Combine(directory, "deno.exe");
338:                 if (File.Exists(path))
339:                     return Path.GetFullPath(path);
340:             }
341:             catch (ArgumentException) { }
342:         }
343:         return null;
344:     }
345: 
346:     internal static void DeleteStaging(string directory)
347:     {
348:         try { Directory.Delete(directory, recursive: true); }
349:         catch (DirectoryNotFoundException) { }
350:         catch (IOException) { }
351:         catch (UnauthorizedAccessException) { }
352:     }
353: 
354:     private sealed record InstalledState(string PackageHash, string InstallId, Dictionary<string, string> FileHashes);
355: }

