309:     private async Task ImportBatchAsync(YtdlpVideo[] videos, YtdlpDownloadOptions options,
310:         TimeSpan cooldown, PlaylistStretchSettings? stretch, int maxParallel, CancellationToken token, DownloadJob[]? retryJobs = null)
311:     {
312:         batchWaitForBpmTag = waitForBpmCheck.Checked;
313:         var batch = InitializeRetryBatch(videos, retryJobs);
314:         using var importGate = new SemaphoreSlim(1, 1);
315:         bool recoveryShown = false, recoveryRetried = false;
316:         try
317:         {
318:             ValidateBatchOutput(options);
319:             await RunBatchPassAsync(batch, batch.Jobs, options, cooldown, stretch, maxParallel, importGate, token);
320:             (recoveryShown, recoveryRetried) = await RecoverBatchAsync(batch, options, cooldown, stretch, maxParallel, importGate, token);
321:         }
322:         catch (OperationCanceledException) when (token.IsCancellationRequested)
323:         {
324:             batch.Cancelled = true;
325:             throw;
326:         }
327:         catch (Exception error)
328:         {
329:             foreach (var job in batch.Jobs.Where(job => !job.Terminal)) RecordJobFailure(job, error);
330:         }
331:         finally
332:         {
333:             batch.Cancelled |= token.IsCancellationRequested;
334:             foreach (var job in batch.Jobs.Where(job => !job.Terminal))
335:                 CompleteJob(job, job.Error is null ? "Cancelled" : "Failed");
336:             batch.Settled = true;
337:             operationClock.Stop();
338:             RefreshOperationTiming();
339:             var failures = batch.Jobs.Where(job => job.Error is not null)
340:                 .Select(job => new InvalidOperationException($"{job.Video.Title} [{job.Video.Id}]: {job.Error!.Message}", job.Error)).ToArray();
341:             AppendLog($"Batch finished: {batch.Jobs.Count(job => job.Status == "Completed")} imported, " +
342:                 $"{failures.Length} failed, {batch.Jobs.Count(job => job.Status == "Cancelled")} cancelled.");
343:             if (failures.Length > 0 && (!recoveryShown || recoveryRetried) && !token.IsCancellationRequested && !closing && !IsDisposed && !resourcesReleased)
344:                 ReportError("Some YouTube imports failed", new AggregateException("Failed imports (including cleanup failures):", failures));
345:         }
346:     }
