356:     private async Task RunImportJobAsync(DownloadBatch batch, DownloadJob job, YtdlpDownloadOptions options,
357:         TimeSpan cooldown, PlaylistStretchSettings? stretch, SemaphoreSlim importGate, CancellationToken token, Action releaseDownloadSlot)
358:     {
359:         using var jobCancellation = CancellationTokenSource.CreateLinkedTokenSource(token);
