410:     private void AutomaticJobRetry(DownloadJob job, YtdlpRetryBudget budget, int attempt, Exception error, bool networkStage)
411:     {
412:         job.Attempt++; // Ignore callbacks queued by a previous attempt.
413:         job.Latest = null;
414:         job.NetworkStage = networkStage;
415:         job.DownloadFinished = !networkStage;
416:         job.AudioStage = false;
417:         job.LastLog = null;
418:         job.Status = $"Retry {attempt}/{budget.MaxRetries}: {(networkStage ? "download / convert" : "audio import")}";
419:         RefreshJob(job);
420:         AppendLog($"[{job.Index + 1}] {job.Video.Title}: {job.Status}; unchanged options. {error.Message}");
