423:     private async Task ImportDownloadedAsync(DownloadBatch batch, DownloadJob job, YtdlpDownloadResult result,
424:         TimeSpan cooldown, PlaylistStretchSettings? stretch, SemaphoreSlim importGate, CancellationToken token, YtdlpRetryBudget retries)
425:     {
426:         Exception? processingError = null;
427:         try
428:         {
429:             await using (result)
430:             {
431:                 try
432:                 {
433:                     // Retry import against the same downloaded file. Downloading again
434:                     // would collide with saved output and lose an external tagger's work.
435:                     await retries.RunAsync(cancellation => CooldownAndImportAsync(batch, job, result, cooldown, stretch, importGate, cancellation), token,
436:                         (attempt, error) => AutomaticJobRetry(job, retries, attempt, error, networkStage: false),
437:                         _ => !job.HandedOff && !job.CancelRequested);
438:                 }
439:                 catch (Exception error) { processingError = error; throw; }
440:                 finally
441:                 {
442:                     job.Status = "Cleaning up";
443:                     RefreshJob(job);
444:                 }
445:             }
446:         }
447:         catch (Exception error) when (job.HandedOff)
448:         {
449:             throw new IOException("Audio was already transferred to the caller; subsequent cleanup failed. Do not import it again automatically.", error);
450:         }
451:         catch (Exception error) when (processingError is not null && !ReferenceEquals(error, processingError))
452:         {
453:             throw new AggregateException("Audio processing and temporary-file cleanup failed.", processingError, error);
454:         }
455:     }
