580:         IReadOnlyList<(int Row, MixClip Clip)> targets, double groupStart, double totalCopies)
581:     {
582:         ArgumentNullException.ThrowIfNull(arrangement); ArgumentNullException.ThrowIfNull(targets);
583:         if (!double.IsFinite(groupStart)) throw new ArgumentOutOfRangeException(nameof(groupStart));
584:         if (!double.IsFinite(totalCopies) || totalCopies < 1 || totalCopies > 64)
585:             throw new ArgumentOutOfRangeException(nameof(totalCopies));
586:         if (targets.Count == 0) return [];
587: 
588:         double groupEnd = targets.Max(target => target.Clip.Start + arrangement.ClipDuration(target.Clip));
589:         double groupDuration = groupEnd - groupStart;
590:         if (!double.IsFinite(groupDuration) || groupDuration <= 0) return [];
591: 
592:         int fullCopies = (int)Math.Floor(totalCopies);
593:         double remainder = totalCopies - fullCopies;
594:         var copies = new List<(int Row, MixClip Clip)>();
595:         static MixClip Clone(MixClip clip) =>
596:             System.Text.Json.JsonSerializer.Deserialize<MixClip>(System.Text.Json.JsonSerializer.Serialize(clip))!;
597: 
598:         for (int repeat = 1; repeat < fullCopies; repeat++)
599:             foreach ((int row, MixClip clip) in targets)
600:             {
601:                 MixClip copy = Clone(clip);
602:                 copy.Id = Guid.NewGuid(); copy.Start = clip.Start + repeat * groupDuration;
603:                 copies.Add((row, copy));
604:             }
605: 
606:         if (remainder > 0.001)
607:         {
608:             double repeatStart = groupStart + fullCopies * groupDuration;
609:             double repeatEnd = repeatStart + remainder * groupDuration;
610:             foreach ((int row, MixClip clip) in targets)
611:             {
612:                 double clipDuration = arrangement.ClipDuration(clip);
613:                 double clipStart = clip.Start + fullCopies * groupDuration;
614:                 double clipEnd = clipStart + clipDuration;
615:                 double visibleStart = Math.Max(clipStart, repeatStart), visibleEnd = Math.Min(clipEnd, repeatEnd);
616:                 if (visibleEnd <= visibleStart) continue;
617: 
618:                 MixClip copy = Clone(clip);
619:                 double rate = arrangement.Rate(clip);
620:                 copy.Id = Guid.NewGuid(); copy.Start = visibleStart;
621:                 copy.SourceOffset += (visibleStart - clipStart) * rate;
622:                 copy.SourceDuration = (visibleEnd - visibleStart) * rate;
623:                 if (visibleStart > clipStart) copy.FadeIn = 0;
624:                 if (visibleEnd < clipEnd) copy.FadeOut = 0;
625:                 copies.Add((row, copy));
626:             }
