1181:     private static float[][] CalculateWavePeaks(MixSource source, int channels, CancellationToken token)
1182:     {
1183:         int frames = source.Data.Length / channels;
1184:         int blocks = (frames + 255) / 256;
1185:         var peaks = Enumerable.Range(0, Math.Min(channels, 8)).Select(_ => new float[blocks]).ToArray();
1186:         for (int frame = 0; frame < frames; frame++)
1187:         {
1188:             if ((frame & 65535) == 0) token.ThrowIfCancellationRequested();
1189:             for (int channel = 0; channel < peaks.Length; channel++)
1190:                 peaks[channel][frame / 256] = Math.Max(peaks[channel][frame / 256], Math.Abs(source.Data[frame * channels + channel]));
1191:         }
1192:         return peaks;
1193:     }
