using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Runtime.InteropServices;
using System.Text.RegularExpressions;
using System.Threading;

namespace ModularAudience.Video;

/// <summary>
/// Represents a video file with lazy, memory-friendly frame extraction.
/// Analogous to <see cref="ModularAudience.Audio.AudioObj"/> but for video.
/// Frames are extracted on demand via FFmpeg and are NOT cached in full — only
/// a small sliding window of recently decoded frames is kept to avoid RAM pressure.
/// </summary>
public sealed class VideoObj : IDisposable
{
    private static readonly Regex DurationRegex = new(@"Duration:\s*(\d{2}):(\d{2}):(\d{2})\.(\d{2})",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);
    private static readonly Regex StreamRegex = new(@"Stream #\d+:\d+\(?(?:video)?\)?.*?(\d{3,4})x(\d{3,4}).*?(\d+(?:\.\d+)?) fps",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);

    private readonly string _filePath;
    private readonly string _ffmpegPath;
    private readonly SemaphoreSlim _decodeGate = new(1, 1);
    private readonly object _disposeLock = new();
    private readonly Dictionary<double, Bitmap> _frameCache = [];
    private readonly List<double> _frameCacheOrder = [];
    private const int MaxCachedFrames = 8;
    private bool _disposed;
    private TimeSpan _duration = TimeSpan.Zero;
    private int _width = 0;
    private int _height = 0;
    private double _frameRate = 0;
    private bool _probeDone = false;

    public string FilePath => _filePath;
    public string Name => Path.GetFileNameWithoutExtension(_filePath);

    public TimeSpan Duration
    {
        get
        {
            EnsureProbed();
            return _duration;
        }
    }

    public int Width
    {
        get
        {
            EnsureProbed();
            return _width;
        }
    }

    public int Height
    {
        get
        {
            EnsureProbed();
            return _height;
        }
    }

    public double FrameRate
    {
        get
        {
            EnsureProbed();
            return _frameRate > 0 ? _frameRate : 30.0;
        }
    }

    public bool HasVideo => Width > 0 && Height > 0 && Duration > TimeSpan.Zero;

    public bool IsDisposed => _disposed;

    public VideoObj(string filePath, string? ffmpegPath = null)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(filePath);
        if (!File.Exists(filePath))
            throw new FileNotFoundException("Video file not found.", filePath);

        _filePath = Path.GetFullPath(filePath);
        _ffmpegPath = ffmpegPath ?? ResolveFfmpegPath();
    }

    private void EnsureProbed()
    {
        if (_probeDone) return;
        Probe();
        _probeDone = true;
    }

    private void Probe()
    {
        string ffprobePath = Path.Combine(Path.GetDirectoryName(_ffmpegPath)!, "ffprobe.exe");
        if (!File.Exists(ffprobePath))
        {
            // Minimal fallback: assume 1080p30, duration unknown until decode.
            _width = 1920; _height = 1080; _frameRate = 30; _duration = TimeSpan.FromMinutes(5);
            return;
        }

        var startInfo = new ProcessStartInfo
        {
            FileName = ffprobePath,
            Arguments = $"-v error -show_entries format=duration -show_entries stream=width,height,r_frame_rate -of default=noprint_wrappers=1:nokey=1 \"{Escape(_filePath)}\"",
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true,
        };

        try
        {
            using var process = Process.Start(startInfo);
            if (process == null) return;
            string output = process.StandardOutput.ReadToEnd();
            process.WaitForExit((int)TimeSpan.FromSeconds(10).TotalMilliseconds);

            var durationMatch = DurationRegex.Match(output);
            if (durationMatch.Success)
            {
                int h = int.Parse(durationMatch.Groups[1].Value, System.Globalization.CultureInfo.InvariantCulture);
                int m = int.Parse(durationMatch.Groups[2].Value, System.Globalization.CultureInfo.InvariantCulture);
                int s = int.Parse(durationMatch.Groups[3].Value, System.Globalization.CultureInfo.InvariantCulture);
                int ms = int.Parse(durationMatch.Groups[4].Value, System.Globalization.CultureInfo.InvariantCulture);
                _duration = new TimeSpan(h, m, s, 0, ms * 10);
            }

            var streamMatch = StreamRegex.Match(output);
            if (streamMatch.Success)
            {
                _width = int.Parse(streamMatch.Groups[1].Value, System.Globalization.CultureInfo.InvariantCulture);
                _height = int.Parse(streamMatch.Groups[2].Value, System.Globalization.CultureInfo.InvariantCulture);
                double fps = double.Parse(streamMatch.Groups[3].Value, System.Globalization.CultureInfo.InvariantCulture);
                _frameRate = fps > 0 ? fps : 30;
            }
        }
        catch
        {
            // Best effort; defaults remain zero/fallback.
        }

        if (_width <= 0) _width = 1920;
        if (_height <= 0) _height = 1080;
        if (_frameRate <= 0) _frameRate = 30;
        if (_duration == TimeSpan.Zero) _duration = TimeSpan.FromMinutes(5);
    }

    /// <summary>
    /// Extracts a single frame at the given time as a low-quality thumbnail.
    /// The returned <see cref="Bitmap"/> must be disposed by the caller.
    /// </summary>
    public async Task<Bitmap?> ExtractFrameAsync(double seconds, int maxWidth = 160, CancellationToken cancellationToken = default)
    {
        EnsureProbed();
        if (_disposed) return null;
        seconds = Math.Clamp(seconds, 0, Duration.TotalSeconds);

        lock (_disposeLock)
        {
            if (_disposed) return null;
            if (_frameCache.TryGetValue(seconds, out var cached))
            {
                _frameCacheOrder.Remove(seconds);
                _frameCacheOrder.Add(seconds);
                return new Bitmap(cached); // caller owns the copy
            }
        }

        await _decodeGate.WaitAsync(cancellationToken).ConfigureAwait(false);
        try
        {
            if (_disposed) return null;
            lock (_disposeLock)
            {
                if (_disposed) return null;
                if (_frameCache.TryGetValue(seconds, out var cached2))
                {
                    _frameCacheOrder.Remove(seconds);
                    _frameCacheOrder.Add(seconds);
                    return new Bitmap(cached2);
                }
            }

            string scale = $"scale={maxWidth}:-2";
            var startInfo = new ProcessStartInfo
            {
                FileName = _ffmpegPath,
                Arguments = $"-ss {seconds:F3} -i \"{Escape(_filePath)}\" -frames:v 1 -vf \"{scale}\" -f image2pipe -vcodec bmp -",
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true,
            };

            using var process = Process.Start(startInfo);
            if (process == null) return null;

            using var ms = new MemoryStream();
            await process.StandardOutput.BaseStream.CopyToAsync(ms, 81920, cancellationToken).ConfigureAwait(false);
            await process.WaitForExitAsync(cancellationToken).ConfigureAwait(false);

            ms.Position = 0;
            var bitmap = new Bitmap(ms);

            lock (_disposeLock)
            {
                if (_disposed) { bitmap.Dispose(); return null; }
                if (_frameCache.Count >= MaxCachedFrames)
                {
                    double oldest = _frameCacheOrder[0];
                    _frameCacheOrder.RemoveAt(0);
                    if (_frameCache.TryGetValue(oldest, out var oldBmp)) oldBmp.Dispose();
                    _frameCache.Remove(oldest);
                }
                _frameCache[seconds] = bitmap;
                _frameCacheOrder.Add(seconds);
            }

            return new Bitmap(bitmap); // caller owns a copy
        }
        catch (OperationCanceledException) { return null; }
        catch { return null; }
        finally { _decodeGate.Release(); }
    }

    /// <summary>
    /// Extracts the audio track to a temporary WAV file path.
    /// Returns null if ffmpeg is unavailable or extraction fails.
    /// </summary>
    public async Task<string?> ExtractAudioToTempWavAsync(CancellationToken cancellationToken = default)
    {
        EnsureProbed();
        if (_disposed) return null;

        string tempPath = Path.Combine(Path.GetTempPath(), $"ModularAudienceVideoAudio_{Guid.NewGuid():N}.wav");

        var startInfo = new ProcessStartInfo
        {
            FileName = _ffmpegPath,
            Arguments = $"-i \"{Escape(_filePath)}\" -vn -acodec pcm_s16le -ar 44100 -ac 2 -y \"{Escape(tempPath)}\"",
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true,
        };

        try
        {
            using var process = Process.Start(startInfo);
            if (process == null) return null;
            await process.WaitForExitAsync(cancellationToken).ConfigureAwait(false);
            if (process.ExitCode != 0 || !File.Exists(tempPath)) return null;
            return tempPath;
        }
        catch { return null; }
    }

    private static string ResolveFfmpegPath()
    {
        // 1. Ytdlp-managed ffmpeg directory
        string ytdlpRoot = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
            "ModularAudience", "binaries_ytdlp");
        try
        {
            if (Directory.Exists(ytdlpRoot))
            {
                foreach (var dir in Directory.EnumerateDirectories(ytdlpRoot, "ffmpeg-*", SearchOption.TopDirectoryOnly))
                {
                    var candidate = Path.Combine(dir, "ffmpeg.exe");
                    if (File.Exists(candidate)) return candidate;
                }
            }
        }
        catch { }

        // 2. Beside entry assembly
        var local = Path.Combine(AppContext.BaseDirectory, "ffmpeg.exe");
        if (File.Exists(local)) return local;

        // 3. PATH
        var pathEnv = Environment.GetEnvironmentVariable("PATH") ?? string.Empty;
        foreach (var entry in pathEnv.Split(Path.PathSeparator))
        {
            var dir = entry.Trim().Trim('"');
            if (string.IsNullOrWhiteSpace(dir) || !Path.IsPathFullyQualified(dir)) continue;
            try
            {
                var candidate = Path.Combine(dir, "ffmpeg.exe");
                if (File.Exists(candidate)) return Path.GetFullPath(candidate);
            }
            catch { }
        }

        return "ffmpeg"; // rely on PATH
    }

    private static string Escape(string argument) => argument.Replace("\"", "\\\"");

    private void Dispose(bool disposing)
    {
        lock (_disposeLock)
        {
            if (_disposed) return;
            _disposed = true;
        }

        if (disposing)
        {
            _decodeGate.Dispose();
            foreach (var kvp in _frameCache) kvp.Value.Dispose();
            _frameCache.Clear();
            _frameCacheOrder.Clear();
        }
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }
}

