using ModularAudience.Audio;
using ModularAudience.Audio.Arrangement;
using ModularAudience.Audio.Processing;
using ModularAudience.Forms.Modules.Dialogs;
using ModularAudience.Shared;
using ModularAudience.Video;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.Json;
using System.Threading;

namespace ModularAudience.Forms.Modules;

public sealed partial class MixTrackView
{
    // ------------------------------------------------------------------
    // Video track — toolbar, import, lane management
    // ------------------------------------------------------------------

    private void AddVideoTrack()
    {
        if (busy || PlaybackLocksEdits) return;
        if (_videoLane != null && !_videoLane.IsDisposed)
        {
            status.Text = "A video track already exists in this mix.";
            return;
        }

        string initialDir = _lastVideoFolder;
        if (string.IsNullOrWhiteSpace(initialDir) || !Directory.Exists(initialDir))
            initialDir = Environment.GetFolderPath(Environment.SpecialFolder.MyVideos);

        using var dialog = new OpenFileDialog
        {
            InitialDirectory = initialDir,
            Filter = "Video files (*.mp4;*.mov;*.avi;*.flv)|*.mp4;*.mov;*.avi;*.flv|All files (*.*)|*.*",
            Multiselect = false,
            Title = "Import video for mix track",
            RestoreDirectory = true
        };

        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try { _lastVideoFolder = Path.GetDirectoryName(dialog.FileName) ?? _lastVideoFolder; } catch { }

        string videoPath = dialog.FileName;
        AddVideoTrackFromPath(videoPath);
    }

    private async void AddVideoTrackFromPath(string videoPath)
    {
        if (busy || PlaybackLocksEdits) return;
        if (!File.Exists(videoPath)) return;

        _ = RunAsync(async token =>
        {
            status.Text = $"Probing video: {Path.GetFileName(videoPath)}…";

            // Probe video with FFmpeg to get dimensions, duration, frame rate.
            VideoObj? video = null;
            try
            {
                video = new VideoObj(videoPath);
                await Task.Yield(); // force async boundary
            }
            catch (Exception ex)
            {
                await ErrorAsync(new InvalidOperationException($"Unable to probe video file: {ex.Message}"));
                return;
            }

            if (!video.HasVideo)
            {
                video.Dispose();
                await ErrorAsync(new InvalidOperationException("The selected file does not contain a usable video stream."));
                return;
            }

            // Create the video lane (only one allowed).
            var videoLane = new MixLane { Name = "Video #1", IsVideo = true, Gain = 1 };
            Arrangement.Lanes.Add(videoLane);
            _videoLane = videoLane;

            // Extract audio from the video to a temp WAV, then load it as an AudioObj source.
            string? tempWav = null;
            try
            {
                tempWav = await video.ExtractAudioToTempWavAsync(token).ConfigureAwait(false);
            }
            catch { tempWav = null; }

            MixSource? audioSource = null;
            if (!string.IsNullOrEmpty(tempWav) && File.Exists(tempWav))
            {
                try
                {
                    using var audioObj = new AudioObj(tempWav, load: true);
                    if (audioObj != null && !audioObj.IsDisposed)
                    {
                        audioSource = new MixSource
                        {
                            Name = $"{video.Name} (audio)",
                            Data = (float[])audioObj.Data.Clone(),
                            SampleRate = audioObj.SampleRate,
                            Channels = audioObj.Channels,
                            Bpm = audioObj.Bpm > 0 ? audioObj.Bpm : audioObj.ScannedBpm,
                            IsVideo = false
                        };
                        Arrangement.Sources.Add(audioSource.Id, audioSource);
                    }
                }
                catch { audioSource = null; }
                finally
                {
                    try { File.Delete(tempWav); } catch { }
                }
            }

            // Create the video source.
            var videoSource = new MixSource
            {
                Name = video.Name,
                IsVideo = true,
                VideoFilePath = videoPath,
                VideoDuration = video.Duration.TotalSeconds,
                VideoWidth = video.Width,
                VideoHeight = video.Height,
                VideoFrameRate = video.FrameRate,
                SampleRate = 44100,
                Channels = 2,
                Bpm = 0,
                Data = []
            };
            Arrangement.Sources.Add(videoSource.Id, videoSource);

            // Add video clip at the end of the video lane (or at 0 if empty).
            double start = 0;
            if (_videoLane.Clips.Count > 0)
                start = _videoLane.Clips.Max(c => c.Start + Arrangement.ClipDuration(c));

            double clipDuration = Math.Min(video.Duration.TotalSeconds, 600); // cap at 10 min per segment for now
            var videoClip = Arrangement.AddClip(_videoLane, videoSource, start, 0, clipDuration)
            {
                IsVideo = true,
                Name = video.Name
            };

            // Add audio clip on a new audio lane directly below the video lane.
            if (audioSource != null)
            {
                var audioLane = new MixLane { Name = "Video Audio #1", Gain = 1 };
                int insertIndex = Arrangement.Lanes.IndexOf(_videoLane) + 1;
                Arrangement.Lanes.Insert(Math.Min(insertIndex, Arrangement.Lanes.Count), audioLane);

                var audioClip = Arrangement.AddClip(audioLane, audioSource, start, 0, audioSource.Duration)
                {
                    IsVideo = false,
                    Name = $"{video.Name} (audio)",
                    LinkedClipId = videoClip.Id
                };
                videoClip.LinkedClipId = audioClip.Id;
            }

            // Pre-extract video frames for thumbnail painting.
            _ = PreExtractVideoFramesAsync(videoClip, video);

            Changed();
            status.Text = $"Video imported: {video.Name} ({video.Width}x{video.Height}, {video.Duration.TotalSeconds:F1}s).";
        });
    }

    private async Task PreExtractVideoFramesAsync(MixClip clip, VideoObj video)
    {
        try
        {
            double duration = Arrangement.ClipDuration(clip);
            int frameCount = Math.Max(4, (int)Math.Ceiling(duration / 0.5)); // one frame every 0.5s
            double step = duration / Math.Max(1, frameCount - 1);

            for (int i = 0; i < frameCount; i++)
            {
                if (_videoLane == null || !Arrangement.Lanes.Contains(_videoLane)) return;
                if (clip.IsDisposedIfSupported()) return;

                double t = i * step;
                Bitmap? frame = await video.ExtractFrameAsync(t, maxWidth: 120, CancellationToken.None).ConfigureAwait(false);
                if (frame != null)
                {
                    lock (_videoFrameCache)
                    {
                        if (_videoFrameCache.Count >= MaxVideoFrameCache)
                        {
                            Guid oldest = _videoFrameCacheOrder[0];
                            _videoFrameCacheOrder.RemoveAt(0);
                            if (_videoFrameCache.TryGetValue(oldest, out var oldBmp)) oldBmp.Dispose();
                            _videoFrameCache.Remove(oldest);
                        }
                        _videoFrameCache[clip.Id] = frame; // keyed by clip, store one representative
                        _videoFrameCacheOrder.Add(clip.Id);
                    }
                }
                await Task.Delay(10).ConfigureAwait(false); // yield to UI
            }
        }
        catch { /* best effort */ }
    }

    // ------------------------------------------------------------------
    // Video frame extraction on demand (hover preview)
    // ------------------------------------------------------------------

    private async Task<Bitmap?> GetVideoFrameAtAsync(MixClip clip, double timeWithinClip, int maxWidth = 240)
    {
        if (clip.SourceId == Guid.Empty) return null;
        if (!Arrangement.Sources.TryGetValue(clip.SourceId, out var source) || !source.IsVideo) return null;

        string? videoPath = source.VideoFilePath;
        if (string.IsNullOrEmpty(videoPath) || !File.Exists(videoPath)) return null;

        VideoObj? video = null;
        try
        {
            video = new VideoObj(videoPath);
            return await video.ExtractFrameAsync(timeWithinClip, maxWidth: maxWidth, CancellationToken.None).ConfigureAwait(false);
        }
        catch { return null; }
        finally { video?.Dispose(); }
    }

    // ------------------------------------------------------------------
    // Video clip painting
    // ------------------------------------------------------------------

    private void DrawVideoClip(Graphics g, int row, MixClip clip, Rectangle rect, bool selected)
    {
        if (!Arrangement.Sources.TryGetValue(clip.SourceId, out var source) || !source.IsVideo) return;

        // Fill background with video clip color.
        Color clipColor = ClipColor(selected ? Arrangement.Visual.SelectedClip : Arrangement.Visual.Clip, row);
        using var brush = new SolidBrush(clipColor);
        g.FillRectangle(brush, rect);

        // Draw frame thumbnails across the clip.
        double duration = Arrangement.ClipDuration(clip);
        if (duration <= 0) return;

        int thumbWidth = Math.Max(16, rect.Width / Math.Max(1, (int)Math.Ceiling(duration / 0.5)));
        int thumbHeight = Math.Max(12, rect.Height - 6);
        int x = rect.X + 2;
        double t = 0;

        while (x + thumbWidth <= rect.Right - 2 && t < duration)
        {
            var thumbRect = new Rectangle(x, rect.Y + 3, thumbWidth, thumbHeight);
            // Draw a placeholder film-strip pattern until async frames arrive.
            using var filmBrush = new SolidBrush(Color.FromArgb(60, 40, 40));
            g.FillRectangle(filmBrush, thumbRect);
            using var filmPen = new Pen(Color.FromArgb(100, 80, 80));
            g.DrawRectangle(filmPen, thumbRect);

            // Sprocket holes.
            using var holeBrush = new SolidBrush(Color.FromArgb(150, 120, 120));
            g.FillRectangle(holeBrush, thumbRect.Left + 2, thumbRect.Top + 2, 3, 3);
            g.FillRectangle(holeBrush, thumbRect.Right - 5, thumbRect.Top + 2, 3, 3);
            g.FillRectangle(holeBrush, thumbRect.Left + 2, thumbRect.Bottom - 5, 3, 3);
            g.FillRectangle(holeBrush, thumbRect.Right - 5, thumbRect.Bottom - 5, 3, 3);

            x += thumbWidth + 2;
            t += 0.5;
        }

        // Clip name label.
        int labelX = Math.Max(Header + 4, rect.X + 4);
        int labelWidth = Math.Max(1, rect.Right - labelX);
        TextRenderer.DrawText(g, clip.Name, Font, new Rectangle(labelX, rect.Y + 2, labelWidth, 16),
            Arrangement.Visual.Text, TextFormatFlags.EndEllipsis);

        // Duration label at right end.
        string durationText = $"{duration:F1}s";
        using var durFont = new Font(Font.FontFamily, 7, FontStyle.Regular);
        TextRenderer.DrawText(g, durationText, durFont, new Rectangle(rect.Right - 30, rect.Bottom - 14, 28, 12),
            Color.FromArgb(180, 180, 180), TextFormatFlags.EndEllipsis | TextFormatFlags.Right);

        // Selection border.
        using var edge = new Pen(selected ? Color.White : Color.FromArgb(110, 150, 165));
        g.DrawRectangle(edge, rect);
        using var handleBrush = new SolidBrush(Color.FromArgb(65, Color.Black));
        g.FillRectangle(handleBrush, rect.X, rect.Y, rect.Width, Math.Min(21, rect.Height));
    }

    private void DrawVideoHoverPreview(Graphics g, MixClip clip, double timeWithinClip, Rectangle clipRect)
    {
        // Small low-quality thumbnail overlay at cursor position within clip.
        // Async frame extraction — placeholder shown until available.
        int previewW = 120, previewH = 68;
        int px = clipRect.X + (int)((timeWithinClip / Math.Max(0.001, Arrangement.ClipDuration(clip))) * clipRect.Width) - previewW / 2;
        int py = clipRect.Top - previewH - 6;
        px = Math.Clamp(px, Header, canvas.Width - previewW);
        py = Math.Max(Ruler + 3, py);

        var previewRect = new Rectangle(px, py, previewW, previewH);
        using var bgBrush = new SolidBrush(Color.FromArgb(230, 20, 20, 20));
        g.FillRectangle(bgBrush, previewRect);
        using var borderPen = new Pen(Color.FromArgb(255, 255, 0), 2);
        g.DrawRectangle(borderPen, previewRect);

        using var filmBrush = new SolidBrush(Color.FromArgb(40, 30, 30));
        g.FillRectangle(filmBrush, previewRect);
        using var filmPen = new Pen(Color.FromArgb(100, 80, 80));
        g.DrawRectangle(filmPen, previewRect);

        TextRenderer.DrawText(g, "Frame", Font, previewRect, Color.Yellow,
            TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis);
    }

    // ------------------------------------------------------------------
    // Video undo /redo (separate stack, max 16)
    // ------------------------------------------------------------------

    private void PushVideoUndo(string beforeJson, string afterJson)
    {
        _videoUndo.Push(JsonSerializer.Serialize(new { Before = beforeJson, After = afterJson }));
        _videoRedo.Clear();
        if (_videoUndo.Count > MaxVideoUndo)
        {
            // Remove oldest entries beyond the limit.
            var arr = _videoUndo.ToArray();
            _videoUndo.Clear();
            for (int i = arr.Length - MaxVideoUndo; i < arr.Length; i++) _videoUndo.Push(arr[i]);
        }
    }

    private void UndoVideo()
    {
        if (busy || PlaybackLocksEdits) return;
        if (_videoUndo.Count == 0) return;

        string entry = _videoUndo.Pop();
        var data = JsonSerializer.Deserialize<VideoUndoEntry>(entry);
        if (data == null) return;

        string before = data.Before; string after = data.After;
        var from = JsonSerializer.Deserialize<VideoUndoState>(undo ? after : before)!;
        var to = JsonSerializer.Deserialize<VideoUndoState>(undo ? before : after)!;

        ApplyVideoUndoState(from, to);
        _videoRedo.Push(entry);
        Changed();
        status.Text = "Video edit undone. Ctrl+Y to redo.";
    }

    private void RedoVideo()
    {
        if (busy || PlaybackLocksEdits) return;
        if (_videoRedo.Count == 0) return;

        string entry = _videoRedo.Pop();
        var data = JsonSerializer.Deserialize<VideoUndoEntry>(entry);
        if (data == null) return;

        string before = data.Before; string after = data.After;
        var from = JsonSerializer.Deserialize<VideoUndoState>(before)!;
        var to = JsonSerializer.Deserialize<VideoUndoState>(after)!;

        ApplyVideoUndoState(from, to);
        _videoUndo.Push(entry);
        Changed();
        status.Text = "Video edit redone. Ctrl+Z to undo.";
    }

    private void ApplyVideoUndoState(VideoUndoState from, VideoUndoState to)
    {
        // Remove lanes not in target.
        foreach (var laneId in from.Lanes.Select(l => l.Id).Except(to.Lanes.Select(l => l.Id)).ToList())
            Arrangement.Lanes.RemoveAll(l => l.Id == laneId);

        // Add/update lanes.
        foreach (var targetLane in to.Lanes)
        {
            var existing = Arrangement.Lanes.FirstOrDefault(l => l.Id == targetLane.Id);
            if (existing == null)
            {
                Arrangement.Lanes.Add(CloneLane(targetLane));
            }
            else
            {
                existing.Name = targetLane.Name;
                existing.Gain = targetLane.Gain;
                existing.Mute = targetLane.Mute;
                existing.Solo = targetLane.Solo;
                existing.IsVideo = targetLane.IsVideo;
                existing.Clips.Clear();
                foreach (var c in targetLane.Clips) existing.Clips.Add(CloneClip(c));
            }
        }

        // Update sources.
        foreach (var s in to.Sources)
        {
            if (!Arrangement.Sources.ContainsKey(s.Id))
                Arrangement.Sources.Add(s.Id, s);
        }
    }

    private static MixLane CloneLane(VideoUndoState.LaneDto dto) => new()
    {
        Id = dto.Id, Name = dto.Name, Gain = dto.Gain, Mute = dto.Mute, Solo = dto.Solo, IsVideo = dto.IsVideo,
        Clips = dto.Clips.Select(CloneClipDto).ToList()
    };

    private static MixClip CloneClipDto(VideoUndoState.ClipDto dto) => new()
    {
        Id = dto.Id, SourceId = dto.SourceId, Name = dto.Name, Start = dto.Start,
        SourceOffset = dto.SourceOffset, SourceDuration = dto.SourceDuration,
        Gain = dto.Gain, FadeIn = dto.FadeIn, FadeOut = dto.FadeOut,
        TempoMode = dto.TempoMode, IsVideo = dto.IsVideo, LinkedClipId = dto.LinkedClipId
    };

