    private void CopyVideoClip()
    {
        if (Clip is not { } clip || !clip.IsVideo) return;
        var source = Arrangement.Sources[clip.SourceId];
        var data = new
        {
            clip.Id,
            clip.SourceId,
            clip.Name,
            clip.Start,
            clip.SourceOffset,
            clip.SourceDuration,
            clip.Gain,
            clip.FadeIn,
            clip.FadeOut,
            clip.TempoMode,
            clip.IsVideo,
            clip.LinkedClipId,
            source.IsVideo,
            source.VideoFilePath,
            source.VideoDuration,
            source.VideoWidth,
            source.VideoHeight,
            source.VideoFrameRate
        };
        string json = JsonSerializer.Serialize(data);
        try { Clipboard.SetText(json); } catch { }
        status.Text = "Video segment copied to clipboard.";
    }

    private void PasteVideoClip()
    {
        if (busy || PlaybackLocksEdits) return;
        string json;
        try { json = Clipboard.GetText(); } catch { return; }
        if (string.IsNullOrWhiteSpace(json)) return;

        try
        {
            var data = JsonSerializer.Deserialize<VideoClipboardData>(json);
            if (data == null || !data.IsVideo || string.IsNullOrEmpty(data.VideoFilePath)) return;

            var row = RowAt(lastPointer.Y);
            if (row < 0 || row >= Arrangement.Lanes.Count) return;

            // Re-register the video source.
            var source = new MixSource
            {
                Name = data.Name,
                IsVideo = true,
                VideoFilePath = data.VideoFilePath,
                VideoDuration = data.VideoDuration,
                VideoWidth = data.VideoWidth,
                VideoHeight = data.VideoHeight,
                VideoFrameRate = data.VideoFrameRate,
                SampleRate = 44100,
                Channels = 2,
                Bpm = 0,
                Data = []
            };
            Arrangement.Sources.Add(source.Id, source);

            var lane = Arrangement.Lanes[row];
            double time = Arrangement.SnapTime(XTime(lastPointer.X), ModifierKeys.HasFlag(Keys.Shift));
            var clip = Arrangement.AddClip(lane, source, time, 0, data.SourceDuration)
            {
                Id = data.Id,
                Name = data.Name,
                SourceOffset = data.SourceOffset,
                SourceDuration = data.SourceDuration,
                Gain = data.Gain,
                FadeIn = data.FadeIn,
                FadeOut = data.FadeOut,
                TempoMode = data.TempoMode,
                IsVideo = true,
                LinkedClipId = data.LinkedClipId
            };
            lane.Clips.Add(clip);
            selectedClip = clip.Id;

            Changed();
            status.Text = "Video segment pasted.";
        }
        catch { /* invalid clipboard data */ }
    }

