    private async Task RenderVideoAsync()
    {
        if (busy || _videoLane == null || _videoLane.Clips.Count == 0) return;

        _ = RunAsync(async token =>
        {
            status.Text = "Rendering video…";

            // Determine output path.
            string? outPath = null;
            try
            {
                string ext = _renderFormat == "avi" ? ".avi" : ".mp4";
                string fileName = $"{Arrangement.Name}_video{ext}";
                using var saveDialog = new SaveFileDialog
                {
                    Filter = _renderFormat == "avi" ? "AVI Video (*.avi)|*.avi" : "MP4 Video (*.mp4)|*.mp4",
                    FileName = fileName,
                    DefaultExt = ext,
                    InitialDirectory = Environment.GetFolderPath(Environment.SpecialFolder.MyVideos),
                    AddExtension = true
                };
                if (await this.ShowMixFileDialogAsync(saveDialog, "Save rendered video") != DialogResult.OK) return;
                outPath = saveDialog.FileName;
            }
            catch { return; }

            // Build ffmpeg command.
            var videoClip = _videoLane.Clips.FirstOrDefault();
            if (videoClip == null) return;
            if (!Arrangement.Sources.TryGetValue(videoClip.SourceId, out var source) || !source.IsVideo) return;
            string? videoPath = source.VideoFilePath;
            if (string.IsNullOrEmpty(videoPath) || !File.Exists(videoPath)) return;

            // Determine resolution.
            string vfScale;
            if (_renderResolution == "keep original")
                vfScale = $"scale={source.VideoWidth}:{source.VideoHeight}";
            else
            {
                var parts = _renderResolution.Split('x');
                if (parts.Length >= 2 && int.TryParse(parts[0], out int w) && int.TryParse(parts[1].Split(' ')[0], out int h))
                    vfScale = $"scale={w}:{h}";
                else
                    vfScale = $"scale={source.VideoWidth}:{source.VideoHeight}";
            }

            string ffmpegPath = ResolveFfmpegPathForRender();
            if (string.IsNullOrEmpty(ffmpegPath))
            {
                await ErrorAsync(new InvalidOperationException("ffmpeg not found. Install ffmpeg to render video."));
                return;
            }

            // Collect audio sources that overlap the video segment(s).
            var audioInputs = new List<(string Path, string Label)>();
            foreach (var lane in Arrangement.Lanes)
            {
                if (lane.IsVideo) continue;
                foreach (var clip in lane.Clips)
                {
                    double clipEnd = clip.Start + Arrangement.ClipDuration(clip);
                    double videoStart = videoClip.Start;
                    double videoEnd = videoClip.Start + Arrangement.ClipDuration(videoClip);
                    if (clip.Start < videoEnd && clipEnd > videoStart)
                    {
                        if (Arrangement.Sources.TryGetValue(clip.SourceId, out var aSrc) && !aSrc.IsVideo)
                        {
                            // Need to render audio clip to temp wav first.
                            audioInputs.Add((clip.SourceId.ToString(), clip.Name));
                        }
                    }
                }
            }

            // Use ProgressDialog for render progress.
            using var cts = new CancellationTokenSource();
            var progress = new Progress<double>(pct =>
            {
                // ProgressDialog handles UI marshaling.
            });

            using var dlg = new ProgressDialog(
                title: "Rendering video…",
                progress: progress,
                windowCloseDelay: 1.0d,
                ct: cts.Token);

            dlg.Show(this);

            try
            {
                // Simple render: just copy video with optional scale, mix audio if available.
                // For MVP, render video only (audio mixing requires complex ffmpeg filtergraph).
                var args = new StringBuilder();
                args.Append($"-i \"{Escape(videoPath)}\" ");
                args.Append($"-vf \"{vfScale}\" ");
                args.Append($"-r {_renderFramerate:F2} ");
                args.Append($"-c:v libx264 -preset fast -crf 23 ");
                args.Append($"-c:a aac -b:a 192k ");
                args.Append($"-y \"{Escape(outPath)}\"");

                var startInfo = new ProcessStartInfo
                {
                    FileName = ffmpegPath,
                    Arguments = args.ToString(),
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };

                using var process = Process.Start(startInfo);
                if (process == null)
                {
                    dlg.Close();
                    await ErrorAsync(new InvalidOperationException("Failed to start ffmpeg."));
                    return;
                }

                // Read stderr for progress.
                var stderrTask = Task.Run(async () =>
                {
                    using var reader = process.StandardError;
                    string? line;
                    while ((line = await reader.ReadLineAsync().ConfigureAwait(false)) != null)
                    {
                        if (token.IsCancellationRequested) break;
                        // ffmpeg reports frame=    fps=  q=  size=    time=...
                        if (line.Contains("time="))
                        {
                            try
                            {
                                var timeMatch = System.Text.RegularExpressions.Regex.Match(line, @"time=(\d{2}):(\d{2}):(\d{2})\.(\d{2})");
                                if (timeMatch.Success)
                                {
                                    int h = int.Parse(timeMatch.Groups[1].Value);
                                    int m = int.Parse(timeMatch.Groups[2].Value);
                                    int s = int.Parse(timeMatch.Groups[3].Value);
                                    int ms = int.Parse(timeMatch.Groups[4].Value);
                                    double current = h * 3600 + m * 60 + s + ms / 100.0;
                                    double total = source.VideoDuration > 0 ? source.VideoDuration : 60;
                                    double pct = Math.Clamp(current / total, 0, 1);
                                    progress.Report(pct);
                                }
                            }
                            catch { }
                        }
                    }
                }, token);

                await process.WaitForExitAsync(token).ConfigureAwait(false);
                await stderrTask.ConfigureAwait(false);

                dlg.Complete();

                if (token.IsCancellationRequested)
                {
                    try { File.Delete(outPath); } catch { }
                    status.Text = "Video render cancelled.";
                    return;
                }

                if (process.ExitCode != 0)
                {
                    await ErrorAsync(new InvalidOperationException($"ffmpeg exited with code {process.ExitCode}."));
                    return;
                }

                status.Text = $"Video rendered: {Path.GetFileName(outPath)}.";
            }
            catch (OperationCanceledException)
            {
                dlg.Close();
                status.Text = "Video render cancelled.";
            }
            catch (Exception ex)
            {
                dlg.Close();
                await ErrorAsync(ex);
            }
        });
    }

    private string ResolveFfmpegPathForRender()
    {
        // Reuse the same resolution logic as VideoObj.
        string ytdlpRoot = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
            "ModularAudience", "binaries_ytdlp");
        try
        {
            if (Directory.Exists(ytdlpRoot))
            {
                foreach (var dir in Directory.EnumerateDirectories(ytdlpRoot, "ffmpeg-*", SearchOption.TopDirectoryOnly))
                {
                    var candidate = Path.Combine(dir, "ffmpeg.exe");
                    if (File.Exists(candidate)) return candidate;
                }
            }
        }
        catch { }

        var local = Path.Combine(AppContext.BaseDirectory, "ffmpeg.exe");
        if (File.Exists(local)) return local;

        var pathEnv = Environment.GetEnvironmentVariable("PATH") ?? string.Empty;
        foreach (var entry in pathEnv.Split(Path.PathSeparator))
        {
            var dir = entry.Trim().Trim('"');
            if (string.IsNullOrWhiteSpace(dir) || !Path.IsPathFullyQualified(dir)) continue;
            try
            {
                var candidate = Path.Combine(dir, "ffmpeg.exe");
                if (File.Exists(candidate)) return Path.GetFullPath(candidate);
            }
            catch { }
        }

        return "ffmpeg";
    }

