private void DrawVideoHoverPreview(Graphics g, MixClip clip, double timeWithinClip, Rectangle clipRect)
{
    // Small low-quality thumbnail overlay at cursor position within clip.
    int previewW = 120, previewH = 68;
    int px = clipRect.X + (int)((timeWithinClip / Math.Max(0.001, Arrangement.ClipDuration(clip))) * clipRect.Width) - previewW / 2;
    int py = clipRect.Top - previewH - 6;
    px = Math.Clamp(px, Header, canvas.Width - previewW);
    py = Math.Max(Ruler + 3, py);

    var previewRect = new Rectangle(px, py, previewW, previewH);
    using var bgBrush = new SolidBrush(Color.FromArgb(230, 20, 20, 20));
    g.FillRectangle(bgBrush, previewRect);
    using var borderPen = new Pen(Color.FromArgb(255, 255, 0), 2);
    g.DrawRectangle(borderPen, previewRect);

    // Try to get a real frame for the hovered time.
    var thumbKey = (clip.Id, Math.Round(timeWithinClip, 3));
    if (_videoThumbCache.TryGetValue(thumbKey, out var thumbBmp))
    {
        g.DrawImage(thumbBmp, previewRect);
    }
    else
    {
        using var filmBrush = new SolidBrush(Color.FromArgb(40, 30, 30));
        g.FillRectangle(filmBrush, previewRect);
        using var filmPen = new Pen(Color.FromArgb(100, 80, 80));
        g.DrawRectangle(filmPen, previewRect);

        System.Windows.Forms.TextRenderer.DrawText(g, "Frame", Font, new Point(previewRect.Left + 2, previewRect.Top + 2), Color.Yellow,
            System.Windows.Forms.TextFormatFlags.HorizontalCenter | System.Windows.Forms.TextFormatFlags.VerticalCenter | System.Windows.Forms.TextFormatFlags.EndEllipsis);

        // Kick off async extraction for hover preview.
        _ = ExtractAndCacheVideoThumbAsync(clip, timeWithinClip, previewW, previewH);
    }
}

// ------------------------------------------------------------------
// Async video frame thumbnail extraction with caching
// ------------------------------------------------------------------

private async Task ExtractAndCacheVideoThumbAsync(MixClip clip, double timeWithinClip, int maxWidth, int maxHeight)
{
    if (!Arrangement.Sources.TryGetValue(clip.SourceId, out var source) || !source.IsVideo) return;
    string? videoPath = source.VideoFilePath;
    if (string.IsNullOrEmpty(videoPath) || !File.Exists(videoPath)) return;

    var thumbKey = (clip.Id, Math.Round(timeWithinClip, 3));

    // Avoid duplicate extractions.
    if (_videoThumbCache.ContainsKey(thumbKey)) return;

    await _videoThumbGate.WaitAsync().ConfigureAwait(false);
    try
    {
        if (_videoThumbCache.ContainsKey(thumbKey)) return;

        VideoObj? video = null;
        try
        {
            video = new VideoObj(videoPath);
            var bmp = await video.ExtractFrameAsync(timeWithinClip, maxWidth: maxWidth, CancellationToken.None).ConfigureAwait(false);
            if (bmp == null) return;

            lock (_videoThumbCache)
            {
                if (_videoThumbCache.Count >= MaxVideoThumbCache)
                {
                    var oldest = _videoThumbCache.Keys.First();
                    if (_videoThumbCache.TryGetValue(oldest, out var oldBmp)) oldBmp.Dispose();
                    _videoThumbCache.Remove(oldest);
                }
                _videoThumbCache[thumbKey] = bmp;
            }

            // Repaint to show the newly extracted frame.
            if (!IsDisposed && !Disposing && IsHandleCreated)
            {
                BeginInvoke((Action)(() => canvas.Invalidate()));
            }
        }
        catch { /* best effort */ }
        finally { video?.Dispose(); }
    }
    finally { _videoThumbGate.Release(); }
}

// ------------------------------------------------------------------

