+
+    private async Task ExtractAndCacheVideoThumbAsync(MixClip clip, double timeWithinClip, int maxWidth, int maxHeight)
+    {
+        if (!Arrangement.Sources.TryGetValue(clip.SourceId, out var source) || !source.IsVideo) return;
+        string? videoPath = source.VideoFilePath;
+        if (string.IsNullOrEmpty(videoPath) || !File.Exists(videoPath)) return;
+
+        var thumbKey = (clip.Id, Math.Round(timeWithinClip, 3));
+
+        // Avoid duplicate extractions.
+        if (_videoThumbCache.ContainsKey(thumbKey)) return;
+
+        await _videoThumbGate.WaitAsync().ConfigureAwait(false);
+        try
+        {
+            if (_videoThumbCache.ContainsKey(thumbKey)) return;
+
+            VideoObj? video = null;
+            try
+            {
+                video = new VideoObj(videoPath);
+                var bmp = await video.ExtractFrameAsync(timeWithinClip, maxWidth: maxWidth, CancellationToken.None).ConfigureAwait(false);
+                if (bmp == null) return;
+
+                lock (_videoThumbCache)
+                {
+                    if (_videoThumbCache.Count >= MaxVideoThumbCache)
+                    {
+                        var oldest = _videoThumbCache.Keys.First();
+                        if (_videoThumbCache.TryGetValue(oldest, out var oldBmp)) oldBmp.Dispose();
+                        _videoThumbCache.Remove(oldest);
+                    }
+                    _videoThumbCache[thumbKey] = bmp;
+                }
+
+                // Repaint to show the newly extracted frame.
+                if (!IsDisposed && !Disposing && IsHandleCreated)
+                {
+                    BeginInvoke((Action)(() => canvas.Invalidate()));
+                }
+            }
+            catch { /* best effort */ }
+            finally { video?.Dispose(); }
+        }
+        finally { _videoThumbGate.Release(); }
+    }
